// Independent read-only reconciliation of this stage's archived raw identities.
using System;using System.IO;using System.Text;using System.Linq;using System.Diagnostics;using System.Collections;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using Microsoft.Win32;
internal static class InspectSingleCleanup {
    static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=64*1024*1024};static List<object> pids=new List<object>();static List<string> problems=new List<string>();static HashSet<string> seen=new HashSet<string>();
    static void Pid(string source,int pid,long? birth,DateTime observed){if(pid<=0||!seen.Add(source+":"+pid+":"+birth))return;IntPtr handle=OpenProcess(0x1000,false,(uint)pid);bool? present=null;long? actual=null;int error=0;bool reused=false;if(handle==IntPtr.Zero){error=Marshal.GetLastWin32Error();if(error==87)present=false;else problems.Add("PID_QUERY_UNKNOWN:"+pid+":"+source);}else try{long c,e,k,u;if(!GetProcessTimes(handle,out c,out e,out k,out u))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());actual=c;reused=birth.HasValue?birth.Value!=c:DateTime.FromFileTimeUtc(c)>observed;present=!reused&&e==0;if(present==true)problems.Add("RECORDED_IDENTITY_LIVE:"+pid+":"+source);}finally{CloseHandle(handle);}pids.Add(new{source,pid,recorded_birth=birth,observed_utc=observed.ToString("o"),present,actual_birth=actual,reused,error});}
    static void Walk(object value,string source,DateTime stamp){var d=value as Dictionary<string,object>;if(d!=null){DateTime parsed;object time;if(d.TryGetValue("utc",out time)&&DateTime.TryParse(Convert.ToString(time),out parsed))stamp=parsed.ToUniversalTime();foreach(string field in new[]{"pid","daemon_pid","broker_pid","launcher_pid","new_daemon_pid","parent_pid"}){object raw;if(!d.TryGetValue(field,out raw))continue;object created;string key=field=="pid"?"created_filetime":field.Replace("_pid","_created_filetime");Pid(source,Convert.ToInt32(raw),d.TryGetValue(key,out created)?(long?)Convert.ToInt64(created):null,stamp);}foreach(var pair in d)Walk(pair.Value,source,stamp);}else if(value is IEnumerable&&!(value is string))foreach(object child in (IEnumerable)value)Walk(child,source,stamp);}
    internal static int Main(string[] args){if(args.Length!=2)return 64;string evidence=Path.GetFullPath(args[0]),output=Path.GetFullPath(args[1]);if(!output.StartsWith(evidence+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||File.Exists(output))return 65;var attempts=new SortedSet<string>();foreach(string kind in new[]{"attempts","node-file-attempts","crash-attempts","daemon-attempts","single-process-host-controls","host-wmi-attempts"}){string parent=Path.Combine(evidence,kind);if(!Directory.Exists(parent))continue;foreach(string directory in Directory.GetDirectories(parent)){Guid id;string nonce=Path.GetFileName(directory);if(!Guid.TryParseExact(nonce,"N",out id))throw new Exception("NONCE");attempts.Add(nonce);foreach(string file in Directory.GetFiles(directory,"*",SearchOption.AllDirectories)){string name=Path.GetFileName(file);if(name=="identity.json"||name=="members.json"||name=="plan.json")continue;if(name.EndsWith(".json"))Walk(J.DeserializeObject(File.ReadAllText(file)),file,File.GetLastWriteTimeUtc(file));else if(name=="events.jsonl")foreach(string line in File.ReadLines(file))Walk(J.DeserializeObject(line),file,File.GetLastWriteTimeUtc(file));}}}
        var resources=new List<object>();foreach(string nonce in attempts){string moniker="specforge.regread."+nonce;bool profile=Directory.Exists(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Packages",moniker)),storage,canary;using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppContainer\Storage\"+moniker,false))storage=key!=null;using(var key=Registry.CurrentUser.OpenSubKey(@"Software\SpecForgeIsolationCanary-"+nonce,false))canary=key!=null;if(profile||storage||canary)problems.Add("RESOURCE_PRESENT:"+nonce);resources.Add(new{attempt=nonce,profile_present=profile,private_storage_present=storage,canary_key_present=canary});}
        var matches=new List<object>();var unknown=new List<int>();foreach(var process in Process.GetProcesses())using(process)try{string image=process.MainModule.FileName;if(new[]{"verification-lpac","verification-lpac-single-host"}.Any(s=>image.StartsWith(Path.GetFullPath(Path.Combine(".tmp",s))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))){matches.Add(new{pid=process.Id,image});problems.Add("SYNTHETIC_IMAGE_LIVE:"+process.Id);}}catch{unknown.Add(process.Id);}var result=new{utc=DateTime.UtcNow.ToString("o"),attempts=resources,processes=pids,matching_synthetic_images=matches,unreadable_unrelated_images=unknown,problems,method="Independent read-only native PID/birth and exact owned resource checks; unrelated unreadable processes not claimed absent",inner_exit_code=problems.Count==0?0:1};using(var file=new FileStream(output,FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(file,new UTF8Encoding(false)))writer.WriteLine(J.Serialize(result));Console.WriteLine(J.Serialize(new{attempts=resources.Count,pid_observations=pids.Count,problems=problems.ToArray(),inner_exit_code=problems.Count==0?0:1}));return problems.Count==0?0:1;
    }
    [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint access,[MarshalAs(UnmanagedType.Bool)]bool inherit,uint pid);
    [DllImport("kernel32.dll",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]static extern bool GetProcessTimes(IntPtr handle,out long created,out long ended,out long kernel,out long user);
    [DllImport("kernel32.dll")][return:MarshalAs(UnmanagedType.Bool)]static extern bool CloseHandle(IntPtr handle);
}
